    AND IF(SIZE(SPLIT(source2_feature_detail,'-')) = 2, SPLIT(source2_feature_detail,'-')[1], NULL) IN ('item', 'video', 'livestream') -- To fulfill page_section IS NULL
    AND source2_feature_detail != source1_feature_detail 
    AND source2_feature_detail != feature_detail;

