CREATE TEMPORARY VIEW dws_search_metrics_${grass_region_without_quote} AS
SELECT
    user_id
    ,state
    ,SUM(CASE WHEN operation = 'impression' THEN operation_cnt ELSE 0 END) AS imp_cnt
    ,SUM(CASE WHEN operation = 'click' THEN operation_cnt ELSE 0 END) AS click_cnt
    ,SUM(CASE WHEN operation = 'order' THEN operation_cnt ELSE 0 END) AS order_cnt
    ,SUM(CASE WHEN operation = 'order' THEN place_order_gmv ELSE 0 END) AS gmv_usd
    ,SUM(CASE WHEN operation = 'order' THEN pc2_gmv ELSE 0 END) AS pc2_usd
FROM
    dwd_search_join_state_${grass_region_without_quote}
GROUP BY
    1, 2;

