--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_main_metrics_${grass_region_without_quote} AS
SELECT
    a.user_id AS user_id
    ,a.state AS state
    ,imp_cnt
    ,click_cnt
    ,order_cnt
    ,gmv_usd
    ,pc2_usd
    ,edt_numerator
    ,edt_denominator
    ,CASE WHEN order_cnt > 0 THEN gmv_usd / order_cnt ELSE 0 END AS abs
FROM
    dws_search_metrics_${grass_region_without_quote} a
LEFT JOIN
    dws_edt_metric_${grass_region_without_quote} b
