CREATE TEMPORARY VIEW user_abs_${grass_region_without_quote} AS
SELECT
    user_id
    ,CASE WHEN SUM(order_cnt) > 0 THEN SUM(gmv_usd) / SUM(order_cnt) ELSE 0 END AS abs
FROM
    dwm_main_metrics_${grass_region_without_quote}
GROUP BY
    1;

--sql_divide_splitter--

CACHE TABLE global_search_abs995_benchmark_${grass_region_without_quote} AS
SELECT
    APPROX_PERCENTILE(IF(abs > 0, abs, NULL), 0.995) as global_search_abs_995
FROM 
    user_abs_${grass_region_without_quote};

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_main_metrics_${grass_region_without_quote} AS
SELECT
/*+ BROADCASTJOIN(c) */
    exp_group_id
    ,IF(state IS NOT NULL, state, '__ALL__') AS state
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv_usd) AS gmv_usd
    ,SUM(IF(abs <= global_search_abs_995, gmv_usd, 0)) as gmv_usd_995
    ,SUM(IF(abs <= global_search_abs_995, gmv_usd, 0)) / COUNT(DISTINCT CASE WHEN imp_cnt > 0 AND abs <= global_search_abs_995 THEN a.user_id END) AS gmv_uu_995
    ,SUM(IF(abs <= global_search_abs_995, pc2_usd, 0)) AS pc2_gmv_usd_995
    ,SUM(IF(abs <= global_search_abs_995, pc2_usd, 0)) / COUNT(DISTINCT CASE WHEN imp_cnt > 0 AND abs <= global_search_abs_995 THEN a.user_id END) AS pc2_gmv_uu_995
    ,SUM(edt_numerator) / SUM(edt_denominator) AS avg_edt
FROM
    dwm_main_metrics_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
JOIN
    global_search_abs995_benchmark_${grass_region_without_quote} c
GROUP BY GROUPING SETS
    ((exp_group_id, state), (exp_group_id));

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_ads_load_denominator_${grass_region_without_quote} AS
