CREATE TEMPORARY VIEW dwd_ads_${grass_region_without_quote} AS
SELECT
    a.user_id AS user_id
    ,COALESCE(state, 'NULL') AS state
    ,SUM(impression_cnt) AS ads_load_numerator
    ,SUM(expenditure_amt_usd) AS ads_rev
    ,SUM(broad_gmv_amt_local) AS ads_broad_roi_numerator_local
    ,SUM(ads_order_gmv_usd) AS ads_narrow_roi_numerator
FROM
    mp_paidads.dwd_advertise_performance_di__reg_s0_live a
LEFT JOIN
