CREATE TEMPORARY VIEW gmv995_v2_item_order_join_${grass_region_without_quote} AS
SELECT
    a.user_id AS user_id
    ,order_id
    ,a.item_id AS item_id
    ,COALESCE(category_tag, 'low gmv') AS category_tag
    ,COALESCE(state, 'NULL') AS state
    ,order_cnt
    ,gmv
    ,pc2_gmv
FROM
    srdi_mart.dws_sr_data_warehouse_platform_order_benchmark_1d a
LEFT JOIN
    user_state_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
LEFT JOIN
    srdi_mart.dim_sr_data_warehouse_item c
ON
    a.item_id = c.item_id
    AND c.local_date = ${local_date}
    AND c.grass_region = ${grass_region}
WHERE
    a.local_date = ${local_date}
    AND a.grass_region = ${grass_region}
    AND a.user_id > 0
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND page_section IS NULL
    AND target_type IN ('item', 'video', 'livestream');

--sql_divide_splitter--

CREATE TEMPORARY VIEW gmv995_v2_item_order_grouped_${grass_region_without_quote} AS
SELECT
    user_id
    ,order_id
    ,item_id
    ,category_tag
    ,IF(GROUPING(state) = 1, '__ALL__', state) AS state
    ,COALESCE(SUM(order_cnt), 0.0) AS order_cnt
    ,COALESCE(SUM(gmv), 0.0) AS gmv
    ,COALESCE(SUM(pc2_gmv), 0.0) AS pc2_gmv
FROM
    gmv995_v2_item_order_join_${grass_region_without_quote}
GROUP BY
    user_id, order_id, item_id, category_tag, CUBE(state);

--sql_divide_splitter--

CREATE TEMPORARY VIEW gmv995_v2_user_filtered_${grass_region_without_quote} AS
SELECT
/*+ BROADCASTJOIN(b) */
    user_id
    ,state
    ,a.category_tag AS category_tag
    ,SUM(IF(gmv <= gmv_995pct, order_cnt, 0)) AS gmv_order_cnt_995_v2
    ,SUM(IF(gmv <= gmv_995pct, gmv, gmv_995pct)) AS gmv_995_v2
    ,SUM(IF(pc2_gmv <= pc2_gmv_995pct, pc2_gmv, pc2_gmv_995pct)) AS pc2_gmv_995_v2
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
FROM
    gmv995_v2_item_order_grouped_${grass_region_without_quote} a
JOIN
    gmv995_v2_outlier_${grass_region_without_quote} b
ON
    a.category_tag = b.category_tag
GROUP BY
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_gmv995_v2_metrics_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,state
    ,SUM(IF(category_tag = 'high gmv', gmv_order_cnt_995_v2, NULL)) AS high_gmv_order_cnt_995_v2
    ,SUM(IF(category_tag = 'high gmv', gmv_995_v2, NULL)) AS high_gmv_995_v2
    ,SUM(IF(category_tag = 'high gmv', pc2_gmv_995_v2, NULL)) AS high_pc2_gmv_995_v2
    ,SUM(IF(category_tag = 'low gmv', gmv_order_cnt_995_v2, NULL)) AS low_gmv_order_cnt_995_v2
    ,SUM(IF(category_tag = 'low gmv', gmv_995_v2, NULL)) AS low_gmv_995_v2
    ,SUM(IF(category_tag = 'low gmv', pc2_gmv_995_v2, NULL)) AS low_pc2_gmv_995_v2
FROM
    gmv995_v2_user_filtered_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY
    1,2;

