INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_state_level_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
/*+ BROADCASTJOIN(d) */
    scene_id
    ,scene_name
    ,layer_id
    ,layer_name
    ,experiment_id
    ,experiment_name
    ,a.exp_group_id AS exp_group_id
    ,exp_group_name
    ,a.state AS state
    ,search_uu
    ,imp_cnt
    ,click_cnt
    ,order_cnt
    ,gmv_usd
    ,gmv_usd_995
    ,gmv_uu_995
    ,pc2_gmv_usd_995
    ,pc2_gmv_uu_995
    ,ads_rev
    ,avg_edt
    ,ads_load
    ,ads_narrow_roi
    ,ads_broad_roi
    ,high_gmv_order_cnt_995_v2
    ,high_gmv_995_v2
    ,high_pc2_gmv_995_v2
    ,low_gmv_order_cnt_995_v2
    ,low_gmv_995_v2
    ,low_pc2_gmv_995_v2
FROM
    dws_main_metrics_${grass_region_without_quote} a
LEFT JOIN
    dws_search_uu_metric_${grass_region_without_quote} b
ON
    a.exp_group_id = b.exp_group_id
    AND a.state = b.state
LEFT JOIN
    dws_ads_${grass_region_without_quote} c
ON
    a.exp_group_id = c.exp_group_id
    AND a.state = c.state
LEFT JOIN
    dim_exp_${grass_region_without_quote} d
ON
    a.exp_group_id = d.exp_group_id
LEFT JOIN
    dws_gmv995_v2_metrics_${grass_region_without_quote} e
ON
    a.exp_group_id = e.exp_group_id
    AND a.state = e.state;
